// Strategy : le calcul de remise varie
const remises = {
  aucune: (total) => total,
  fidelite: (total) => total * 0.95,
  solde: (total) => total * 0.8
};

function prixFinal(total, type) {
  const appliquer = remises[type] ?? remises.aucune;
  return appliquer(total);
}

